#!/usr/bin/env bash
# ============================================================================
# setup_ai_harness.sh — 通用 C++ 项目 AI 编程 Harness 一键初始化
#
# 用法：在项目根目录执行
#   bash setup_ai_harness.sh --detect-project [--json]
#   bash setup_ai_harness.sh [--force] [--project-profile <path>]
#   bash setup_ai_harness.sh --migrate-openspec [--dry-run] [--project-profile <path>]
#
# 默认生成 OpenSpec-aware Harness：
#   openspec/                 — proposal/specs/design/tasks 与归档历史
#   openspec/changes/<id>/harness/ — verification、footprint、Evaluation、RCA
#   scripts/openspec_*.sh、change_*.sh、task_verify.sh、evaluator_check.sh
#   PROJECT_ATTRIBUTION.md   — 项目级作者署名与权利边界
#   CLAUDE.md、AGENTS.md、docs/ai/、prompts/ — 角色与工程治理入口
#   ai_snapshot.json          — 唯一 active change selector（schema v2）
#   .ai-harness/              — manifest 与本机 lock/log/migration 状态
#
# 只生成统一 OpenSpec 工作流。旧版根 spec/todo/tasks 制品只能通过
# `--migrate-openspec` 进入该工作流，不能再初始化第二套事实源。
#
# 初始化依赖：Git、Node >=20.19.0、npm、npx、OpenSpec 1.6.0。
# ============================================================================

set -euo pipefail

SETUP_SOURCE_DIR=$(CDPATH= cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)
SETUP_SOURCE_PATH="$SETUP_SOURCE_DIR/$(basename -- "${BASH_SOURCE[0]}")"
FORCE=0
WORKFLOW_MODE="openspec"
MIGRATE_OPEN_SPEC=0
DRY_RUN=0
DETECT_PROJECT=0
OUTPUT_JSON=0
PROJECT_PROFILE_PATH=
PROJECT_PROFILE_SOURCE=
PROJECT_PROFILE_TEMP=
PROJECT_PROFILE_EXPECTED_SHA=
PROJECT_PROFILE_INSTALLED=0
MIGRATION_OVERWRITE=0
MIGRATION_MANIFEST_PATH=
MANIFEST_TEMPLATE_UPGRADE_PATHS=()
BACKUP_SUFFIX="$(date +%Y%m%d%H%M%S)"
AUTOAI_HARNESS_VERSION="4.0.0"
OPENSPEC_PACKAGE="@fission-ai/openspec"
OPENSPEC_VERSION="1.6.0"
MIN_NODE_VERSION="20.19.0"

usage() {
    cat <<'EOF'
用法：
  bash setup_ai_harness.sh --detect-project [--json]
  bash setup_ai_harness.sh [--force] [--project-profile <path>]
  bash setup_ai_harness.sh --migrate-openspec [--dry-run] [--project-profile <path>]

选项：
  --detect-project     只读探测项目模块与构建候选；不要求 Node/npm/npx
  --json               仅与 --detect-project 一起使用，输出机器可读候选
  --project-profile    使用已审核的 Project Profile；不会被 --force 覆盖
  --force              备份并更新 AutoAI 管理的模板；不覆盖状态或 OpenSpec 制品
  --migrate-openspec   将已识别的 legacy Harness 安全迁移到 OpenSpec
  --dry-run            仅与 --migrate-openspec 一起使用；只分类和报告，不写工作区
  --version            显示 Harness 版本
  -h,--help            显示帮助

默认行为：使用团队 Project Profile 生成 OpenSpec-aware Harness。
固定使用 @fission-ai/openspec@1.6.0；不再提供 legacy Harness 初始化模式。
EOF
}

while [ "$#" -gt 0 ]; do
    case "$1" in
        --force)
            FORCE=1
            ;;
        --detect-project)
            DETECT_PROJECT=1
            ;;
        --json)
            OUTPUT_JSON=1
            ;;
        --project-profile)
            [ "$#" -ge 2 ] || {
                echo "[ERR] --project-profile 缺少路径" >&2
                exit 2
            }
            [ -z "$PROJECT_PROFILE_PATH" ] || {
                echo "[ERR] --project-profile 不能重复" >&2
                exit 2
            }
            PROJECT_PROFILE_PATH=$2
            shift
            ;;
        --migrate-openspec)
            MIGRATE_OPEN_SPEC=1
            WORKFLOW_MODE="migration"
            ;;
        --dry-run)
            DRY_RUN=1
            ;;
        -h|--help)
            usage
            exit 0
            ;;
        --version)
            printf 'AutoAI Harness %s\n' "$AUTOAI_HARNESS_VERSION"
            exit 0
            ;;
        *)
            echo "[ERR] 未知参数: $1" >&2
            usage
            exit 2
            ;;
    esac
    shift
done

if [ "$DRY_RUN" -eq 1 ] && [ "$MIGRATE_OPEN_SPEC" -ne 1 ]; then
    echo "[ERR] --dry-run 只能与 --migrate-openspec 一起使用" >&2
    exit 2
fi
if [ "$FORCE" -eq 1 ] && [ "$MIGRATE_OPEN_SPEC" -eq 1 ]; then
    echo "[ERR] --force 不能用于迁移；迁移有独立的备份和恢复协议" >&2
    exit 2
fi
if [ "$OUTPUT_JSON" -eq 1 ] && [ "$DETECT_PROJECT" -ne 1 ]; then
    echo "[ERR] --json 只能与 --detect-project 一起使用" >&2
    exit 2
fi
if [ "$DETECT_PROJECT" -eq 1 ]; then
    if [ "$FORCE" -eq 1 ] || [ "$MIGRATE_OPEN_SPEC" -eq 1 ] || [ "$DRY_RUN" -eq 1 ] || \
       [ -n "$PROJECT_PROFILE_PATH" ]; then
        echo "[ERR] --detect-project 不能与写入、迁移或 Profile 参数组合" >&2
        exit 2
    fi
    WORKFLOW_MODE="detect"
fi

# --- 颜色 ---
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
RED='\033[0;31m'
NC='\033[0m'

info()  { echo -e "${BLUE}[INFO]${NC}  $*"; }
ok()    { echo -e "${GREEN}[OK]${NC}    $*"; }
skip()  { echo -e "${YELLOW}[SKIP]${NC}  $* (已存在)"; }
err()   { echo -e "${RED}[ERR]${NC}   $*"; }

