trusted_manifest_contract_is_valid() {
    {
        manifest_policy_content
        printf '%s\n' "try { module.exports.loadManifest(process.cwd(), {allowTemplateUpgrade:true,verifyContent:false}); } catch (e) { console.error('[ERR] '+e.message); process.exit(6); }"
    } | node >/dev/null 2>&1
}

trusted_manifest_upgrade_paths() {
    {
        manifest_policy_content
        printf '%s\n' "try { const r=module.exports.loadManifest(process.cwd(), {allowTemplateUpgrade:true,verifyContent:false}); process.stdout.write(r.missing_managed_paths.join('\\n')+(r.missing_managed_paths.length?'\\n':'')); } catch (e) { console.error('[ERR] '+e.message); process.exit(6); }"
    } | node
}

installed_manifest_policy_matches_template() {
    local expected
    expected=$(mktemp "${TMPDIR:-/tmp}/autoai-manifest-policy.XXXXXX") || return 1
    manifest_policy_content > "$expected"
    cmp -s -- "$expected" scripts/manifest_policy.js
    local rc=$?
    rm -f -- "$expected"
    return "$rc"
}

write_control_scripts() {
    template_write scripts/attribution_check.sh 755 < <(attribution_check_content)
    template_write scripts/manifest_policy.js 755 < <(manifest_policy_content)
    template_write scripts/harness_lock.sh 755 <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
HARNESS_REPO_ROOT=$(git rev-parse --show-toplevel 2>/dev/null) || { echo "[ERR] Git repository required" >&2; return 3 2>/dev/null || exit 3; }
[[ "$(pwd -P)" == "$(CDPATH= cd -- "$HARNESS_REPO_ROOT" && pwd -P)" ]] || { echo "[ERR] run from repository root" >&2; return 3 2>/dev/null || exit 3; }
HARNESS_LOCK_DIR="$HARNESS_REPO_ROOT/.ai-harness/locks/managed-operation.lock"
HARNESS_OWNED_LOCK=0
HARNESS_OWNED_TOKEN=
HARNESS_EFFECTIVE_PURPOSE=
HARNESS_EFFECTIVE_CHANGE=

harness_assert_repo_path() {
    local relative=${1:?relative path required} kind=${2:?path kind required}
    node - "$HARNESS_REPO_ROOT" "$relative" "$kind" <<'NODE'
