if(!['dir','dir-or-missing','file','file-or-missing'].includes(kind)||!rel||path.posix.isAbsolute(rel)||rel.includes('\\')||rel.includes('\0')||rel.includes('\n')||rel.includes('\r')||parts.some(x=>!x||x==='.'||x==='..'))process.exit(4);
