NODE
}
harness_prepare_runtime_dir() {
    local name=${1:?runtime directory required}
    local relative=".ai-harness/$name"
    [[ "$name" =~ ^(locks|logs|migrations)$ ]] || return 4
    harness_assert_repo_path .ai-harness dir || { echo "[ERR] unsafe .ai-harness directory" >&2; return 4; }
    harness_assert_repo_path "$relative" dir-or-missing || { echo "[ERR] unsafe runtime directory: $relative" >&2; return 4; }
    if [[ ! -e "$relative" ]]; then mkdir -- "$relative" || return 4; fi
    harness_assert_repo_path "$relative" dir || return 4
}
harness_assert_changes_root() {
    harness_assert_repo_path openspec dir &&
        harness_assert_repo_path openspec/changes dir &&
        harness_assert_repo_path openspec/changes/archive dir
}
harness_assert_change_dir() {
    local change=${1:?change required}
    harness_validate_change_id "$change" || return
    harness_assert_repo_path openspec dir &&
        harness_assert_repo_path openspec/changes dir &&
        harness_assert_repo_path "openspec/changes/$change" dir
}
harness_assert_change_harness() {
    local change=${1:?change required}
    harness_assert_change_dir "$change" && harness_assert_repo_path "openspec/changes/$change/harness" dir
}
harness_archive_failure_optional() {
    harness_assert_repo_path ai_snapshot.json file || return 4
