if(!st.isFile()||st.isSymbolicLink())process.exit(4);let t;try{t=JSON.parse(fs.readFileSync(transactionFile))}catch{process.exit(4)}
const keys=['schema_version','transaction_id','change_name','status','prepared_at','completed_at','target_path','log_path','root_snapshot_sha256','fingerprints','evidence_sha256'];
const closed=t&&typeof t==='object'&&!Array.isArray(t)&&Object.keys(t).length===keys.length&&keys.every(k=>Object.prototype.hasOwnProperty.call(t,k));
const digest=v=>typeof v==='string'&&/^sha256:[0-9a-f]{64}$/.test(v),safeRel=v=>typeof v==='string'&&v&&!path.posix.isAbsolute(v)&&path.posix.normalize(v)===v&&!v.includes('\\')&&!v.includes('\0')&&!/[\r\n]/.test(v)&&v!=='.git'&&!v.startsWith('.git/');
if(!closed||t.schema_version!==1||!/^archive-txn-[0-9a-f]{24}$/.test(t.transaction_id)||typeof t.change_name!=='string'||!['prepared','committed','acknowledged'].includes(t.status)||!Number.isFinite(Date.parse(t.prepared_at))||t.status==='prepared'&&t.completed_at!==null||t.status!=='prepared'&&!Number.isFinite(Date.parse(t.completed_at))||!safeRel(t.target_path)||!safeRel(t.log_path)||!digest(t.root_snapshot_sha256)||!t.fingerprints||!digest(t.fingerprints.source_fingerprint)||!digest(t.fingerprints.artifact_fingerprint)||!digest(t.fingerprints.base_specs_fingerprint)||t.fingerprints.profile_sha256!==undefined&&!digest(t.fingerprints.profile_sha256)||!digest(t.evidence_sha256))process.exit(4);
