harness_require_no_archive_failure() {
    local failed active purpose
    failed=$(harness_archive_failure_optional) || return 4
    [[ -z "$failed" ]] || { echo "[ERR] archive recovery is unresolved for $failed; inspect logs and use scripts/archive_recover.sh" >&2; return 4; }
    active=$(harness_active_optional) || return 4
    if [[ -n "$active" ]]; then
        purpose=$(cat "$HARNESS_LOCK_DIR/purpose" 2>/dev/null || true)
        harness_require_no_prepared_integration_upgrade "$active" "$purpose" || return
    fi
