try{const resolved=cp.execFileSync('git',['rev-parse','--verify',snapshot.implementation_base_commit+'^{commit}'],{encoding:'utf8'}).trim();if(resolved!==snapshot.implementation_base_commit)process.exit(6);cp.execFileSync('git',['merge-base','--is-ancestor',snapshot.implementation_base_commit,'HEAD'],{stdio:'ignore'})}catch{process.exit(6)}
