harness_validate_change_id() {
    local id=${1:-}
    [[ "$id" =~ ^[a-z][a-z0-9]*(-[a-z0-9]+)*$ && "$id" != archive && "$id" != archive-* && "$id" != stale && "$id" != stale-* ]] || { echo "[ERR] invalid change ID: ${id:-<empty>}" >&2; return 2; }
}
harness_active_optional() {
    harness_assert_repo_path ai_snapshot.json file || return 4
    node - "$HARNESS_REPO_ROOT/ai_snapshot.json" <<'NODE'
const fs=require('fs'),f=process.argv[2],s=fs.lstatSync(f),v=JSON.parse(fs.readFileSync(f));if(!s.isFile()||s.isSymbolicLink()||v.schema_version!==2||v.workflow!=='openspec'||v.active_change!==null&&typeof v.active_change!=='string')process.exit(6);if(v.active_change)process.stdout.write(v.active_change);
NODE
}
harness_resolve_change() {
    local requested=${1:-} active; active=$(harness_active_optional) || return 6
    if [[ -n "$requested" ]]; then harness_validate_change_id "$requested" || return; [[ -n "$active" ]] || { echo "[ERR] no active change; select '$requested' explicitly before managed work" >&2; return 4; }; [[ "$requested" == "$active" ]] || { echo "[ERR] requested '$requested' is not active '$active'" >&2; return 4; }; printf '%s\n' "$requested"
    elif [[ -n "$active" ]]; then harness_validate_change_id "$active" || return; printf '%s\n' "$active"
    else echo "[ERR] no active change; select one explicitly" >&2; return 4; fi
}
harness_lock_release() {
    if [[ "$HARNESS_OWNED_LOCK" -eq 1 ]] && harness_assert_repo_path .ai-harness/locks dir >/dev/null 2>&1 && harness_assert_repo_path .ai-harness/locks/managed-operation.lock dir >/dev/null 2>&1 && [[ -f "$HARNESS_LOCK_DIR/token" && ! -L "$HARNESS_LOCK_DIR/token" && "$(cat "$HARNESS_LOCK_DIR/token" 2>/dev/null || true)" == "$HARNESS_OWNED_TOKEN" ]]; then rm -rf -- "$HARNESS_LOCK_DIR"; fi
}
harness_lock_acquire() {
    local purpose=${1:?purpose required} change=${2:-} owner_purpose declared_parent lock_file lock_pid owner_pid
    harness_prepare_runtime_dir locks || { echo "[ERR] unsafe Harness lock directory" >&2; return 4; }
    if [[ -n "${AUTOAI_LOCK_TOKEN:-}" ]]; then
        harness_assert_repo_path .ai-harness/locks/managed-operation.lock dir || { echo "[ERR] unsafe inherited lock directory" >&2; return 4; }
        for lock_file in token change purpose pid; do harness_assert_repo_path ".ai-harness/locks/managed-operation.lock/$lock_file" file || { echo "[ERR] unsafe inherited lock metadata" >&2; return 4; }; done
        [[ -f "$HARNESS_LOCK_DIR/token" && "$(cat "$HARNESS_LOCK_DIR/token")" == "$AUTOAI_LOCK_TOKEN" ]] || { echo "[ERR] inherited lock token mismatch" >&2; return 4; }
        [[ "$(cat "$HARNESS_LOCK_DIR/change" 2>/dev/null || true)" == "$change" ]] || { echo "[ERR] inherited lock change mismatch" >&2; return 4; }
        lock_pid=$(cat "$HARNESS_LOCK_DIR/pid" 2>/dev/null || true)
        [[ "$lock_pid" =~ ^[0-9]+$ && "$lock_pid" -gt 1 ]] && kill -0 "$lock_pid" 2>/dev/null || { echo "[ERR] inherited lock owner is not alive" >&2; return 4; }
        owner_purpose=$(cat "$HARNESS_LOCK_DIR/purpose" 2>/dev/null || true); declared_parent=${AUTOAI_PARENT_PURPOSE:-}
