}
harness_lock_bind_change() {
    local change=${1:?change required} current_purpose
    harness_validate_change_id "$change" || return
    harness_assert_change_harness "$change" || { echo "[ERR] unsafe change or harness directory: $change" >&2; return 4; }
    if [[ -n "${AUTOAI_LOCK_TOKEN:-}" ]]; then
        [[ "$(cat "$HARNESS_LOCK_DIR/change" 2>/dev/null || true)" == "$change" ]] || { echo "[ERR] inherited lock change mismatch" >&2; return 4; }
    else
        [[ "$HARNESS_OWNED_LOCK" -eq 1 && "$(cat "$HARNESS_LOCK_DIR/token")" == "$HARNESS_OWNED_TOKEN" ]] || return 4
        printf '%s\n' "$change" > "$HARNESS_LOCK_DIR/change"
    fi
    current_purpose=$(cat "$HARNESS_LOCK_DIR/purpose" 2>/dev/null || true)
    HARNESS_EFFECTIVE_CHANGE=$change
    harness_require_no_prepared_integration_upgrade "$change" "$current_purpose" || return
    if declare -F harness_require_isolation_authority >/dev/null; then
        harness_require_isolation_authority "$change" "$current_purpose" || return
    fi
}
harness_with_verification_workspace_capability() {
    local change=${1:?change required} action=${2:?action required}
    shift 2
    local owner_token lock_pid owner_purpose capability token_file="$HARNESS_LOCK_DIR/verification-workspace-token" rc=0 capability_state
    [[ $# -gt 0 && "$action" =~ ^(run|cleanup|assert-clean)$ ]] || return 2
    harness_validate_change_id "$change" || return
    harness_assert_repo_path scripts/verification_workspace.sh file || return 4
    [[ "$(scripts/verification_workspace.sh --protocol 2>/dev/null || true)" == autoai-verification-workspace-v2 ]] || {
        echo '[ERR] verification workspace receiver protocol is missing or incompatible; rerun Harness setup before managed work' >&2
        return 4
    }
    case "$action" in
        run)
            [[ $# -ge 5 && ( "$1" == scripts/verification_workspace.sh || "$1" == ./scripts/verification_workspace.sh ) &&
               "$2" == run && "$3" == "$change" && "$4" == -- ]] || {
                echo '[ERR] verification workspace run capability does not match the exact wrapper command' >&2
                return 4
            }
            ;;
        cleanup|assert-clean)
            [[ $# -eq 3 && ( "$1" == scripts/verification_workspace.sh || "$1" == ./scripts/verification_workspace.sh ) &&
               "$2" == "$action" && "$3" == "$change" ]] || {
                echo '[ERR] verification workspace control capability does not match the exact action' >&2
                return 4
            }
            ;;
    esac
    harness_assert_repo_path .ai-harness/locks/managed-operation.lock dir || return 4
    for file in token pid purpose change; do
        harness_assert_repo_path ".ai-harness/locks/managed-operation.lock/$file" file || return 4
    done
