        [[ "$HARNESS_OWNED_LOCK" -eq 1 && -n "$HARNESS_OWNED_TOKEN" ]] || {
            echo '[ERR] verification workspace capability requires the current managed lock owner' >&2
            return 4
        }
        owner_token=$HARNESS_OWNED_TOKEN
    fi
    [[ "$(cat "$HARNESS_LOCK_DIR/token" 2>/dev/null || true)" == "$owner_token" &&
       "$(cat "$HARNESS_LOCK_DIR/change" 2>/dev/null || true)" == "$change" ]] || {
        echo '[ERR] managed lock identity does not authorize a verification workspace capability' >&2
        return 4
    }
