const fs=require('fs'),crypto=require('crypto'),[file,token,change,action,ownerPurpose,effectivePurpose,pidText,lockToken]=process.argv.slice(2),sha=v=>'sha256:'+crypto.createHash('sha256').update(v).digest('hex'),pid=Number(pidText),value={schema_version:1,token_sha256:sha(token),change_name:change,action,owner_purpose:ownerPurpose,effective_purpose:effectivePurpose,owner_pid:pid,lock_token_sha256:sha(lockToken),issued_at:new Date().toISOString()};if(!/^[0-9a-f]{48}$/.test(token)||!Number.isInteger(pid)||pid<=1)process.exit(4);fs.writeFileSync(file,JSON.stringify(value,null,2)+'\n',{mode:0o600,flag:'wx'});const st=fs.lstatSync(file),uid=typeof process.geteuid==='function'?process.geteuid():st.uid;if(!st.isFile()||st.isSymbolicLink()||st.uid!==uid||(st.mode&0o077)!==0)process.exit(4);
