        echo '[ERR] another verification workspace capability is active or unsafe' >&2
        return 4
    }
    if AUTOAI_VERIFICATION_WORKSPACE_TOKEN="$capability" "$@"; then rc=0; else rc=$?; fi
    capability_state=$(
        node - "$token_file" "$capability" "$change" "$action" "$owner_purpose" "$HARNESS_EFFECTIVE_PURPOSE" "$lock_pid" "$owner_token" <<'NODE'
const fs=require('fs'),crypto=require('crypto'),[file,token,change,action,ownerPurpose,effectivePurpose,pidText,lockToken]=process.argv.slice(2),sha=v=>'sha256:'+crypto.createHash('sha256').update(v).digest('hex');let st;try{st=fs.lstatSync(file)}catch(e){if(e.code==='ENOENT'){process.stdout.write('consumed');process.exit(0)}throw e}const uid=typeof process.geteuid==='function'?process.geteuid():st.uid,d=JSON.parse(fs.readFileSync(file));if(!st.isFile()||st.isSymbolicLink()||st.uid!==uid||(st.mode&0o077)!==0||d.schema_version!==1||d.token_sha256!==sha(token)||d.change_name!==change||d.action!==action||d.owner_purpose!==ownerPurpose||d.effective_purpose!==effectivePurpose||d.owner_pid!==Number(pidText)||d.lock_token_sha256!==sha(lockToken))process.exit(4);fs.unlinkSync(file);process.stdout.write('unconsumed');
