harness_verification_workspace_control() {
    local action=${1:?action required} change=${2:?change required}
    [[ "$action" == cleanup || "$action" == assert-clean ]] || return 2
    harness_with_verification_workspace_capability "$change" "$action" \
        scripts/verification_workspace.sh "$action" "$change"
}
harness_run_evidence_command() {
    local change=${1:?change required}
    shift
    [[ $# -gt 0 ]] || return 2
    case "$1" in
        scripts/verification_workspace.sh|./scripts/verification_workspace.sh)
            harness_with_verification_workspace_capability "$change" run "$@"
            ;;
        *) "$@" ;;
    esac
}
harness_persist_project_command_evidence() {
    local change=${1:?change required} command_id=${2:?command ID required}
    local exit_code=${3:?exit code required} output_sha256=${4:?output digest required}
    local output_file=${5:?output file required}
    node - "$change" "$command_id" "$exit_code" "$output_sha256" "$output_file" <<'NODE'
const [change,commandId,exitCode,outputSha,outputFile]=process.argv.slice(2);
require(process.cwd()+'/scripts/manifest_policy.js').persistProjectCommandEvidence(
  process.cwd(),change,commandId,Number(exitCode),outputSha,outputFile
);
NODE
}
harness_require_closing_project_command_output() {
    local output_file=${1:?output file required}
    node - "$output_file" <<'NODE'
const fs=require('fs'),envelope=JSON.parse(fs.readFileSync(process.argv[2],'utf8'));
if(['TimedOut','Cancelled'].includes(envelope.status)||envelope.signal!==null)process.exit(1);
