    const astResult = runTool(tool, [...flags, '-fsyntax-only', '-Xclang', '-ast-dump=json', source], compileDirectory, tempRoot, MAX_AST_BYTES);
    const ast = parseJsonNoDuplicates(decode(astResult.stdout, 'clang_ast'), 'clang_ast');
