run_openspec_harness() {
    preflight_dependencies
    preflight_openspec_runner
    preflight_openspec_state
    prepare_project_profile_input
    local fresh=0
    [[ -f openspec/config.yaml ]] || fresh=1
    collect_openspec_inputs
    info "即将写入 OpenSpec-aware Harness；不会提交 Git，也不会覆盖 Team/OpenSpec 制品。"
    acquire_setup_lock
    # Recheck target-owned state under the shared lock before the first write.
    preflight_openspec_state
    [[ -f openspec/config.yaml ]] && fresh=0
    mkdir -p .ai-harness/logs .ai-harness/migrations
    write_openspec_runner
    if [[ "$fresh" -eq 1 ]]; then
        write_initial_openspec_config
        scripts/openspec_cli.sh init . --tools none --profile core || die 6 "OpenSpec init 失败；不会回退到 legacy"
        if find .claude .codex -mindepth 1 \( -name 'openspec-*' -o -name 'opsx' -o -name 'opsx-*' \) -print -quit 2>/dev/null | grep -q .; then
            die 6 "OpenSpec init 生成了首版不支持的 /opsx Agent assets；已停止，保留现场供人工检查"
        fi
    fi
    mkdir -p openspec/specs openspec/changes/archive
    [[ -f openspec/config.yaml && -d openspec/specs && -d openspec/changes/archive ]] || die 6 "OpenSpec init 后置目录检查失败"
    if [[ "$fresh" -eq 1 ]]; then
        local validation
        validation=$(mktemp "${TMPDIR:-/tmp}/autoai-init-validation.XXXXXX")
        if ! scripts/openspec_cli.sh validate --all --strict --json --no-interactive > "$validation"; then rm -f "$validation"; die 6 "OpenSpec strict validation 失败"; fi
        if ! validation_json_is_clean "$validation"; then rm -f "$validation"; die 6 "OpenSpec strict validation JSON 含错误"; fi
        rm -f "$validation"
    fi
    install_project_profile
    write_governance_templates
    write_control_scripts
    write_project_portability_scripts
    write_project_coordination_scripts
    write_integration_scripts
    write_change_scripts
    write_utility_scripts
    write_fingerprint_script
    write_footprint_script
    write_task_verify_script
    write_evaluator_script
    write_archive_script
    write_openspec_state
    write_openspec_manifest
    append_managed_gitignore
    scripts/attribution_check.sh --quiet || die 6 "项目署名契约校验失败；Harness 未完成初始化"
    scripts/project_profile.sh --check >/dev/null || die 6 "Project Profile 校验失败；Harness 未完成初始化"
    AUTOAI_SETUP_SOURCE="$SETUP_SOURCE_PATH" \
      AUTOAI_SETUP_TEST_ROOT="$SETUP_SOURCE_DIR/tests/openspec-integration/cases" \
      scripts/workflow_contract_check.sh >/dev/null || die 6 "工作流契约一致性校验失败；Harness 未完成初始化"
    release_setup_lock
    trap - EXIT INT TERM HUP
    ok "OpenSpec-aware Harness 初始化完成"
    echo "项目：$PROJECT_NAME | Profile：$PROJECT_PROFILE_EXPECTED_SHA"
    echo "署名：本项目由“cpp辅导的阿甘”开发。"
    echo "下一步：scripts/change_new.sh <kebab-name>，完成规划并人工审核后再进入 Generator。"
}


LEGACY_OWNED=()
LEGACY_AMBIGUOUS=()
LEGACY_DELETE=()
LEGACY_DELETE_DIRS=()
LEGACY_SOURCE_COUNT=0

legacy_array_contains() {
    local needle=$1 item
    shift
    for item in "$@"; do [[ "$item" == "$needle" ]] && return 0; done
    return 1
}

legacy_record_ambiguous() {
    local path=$1
    legacy_array_contains "$path" "${LEGACY_AMBIGUOUS[@]}" || LEGACY_AMBIGUOUS+=("$path")
}

legacy_add_candidate() {
    local path=$1 marker=$2 delete_after=$3
    [[ -e "$path" || -L "$path" ]] || return 0
    if [[ "$path" == *$'\n'* || -L "$path" || ! -f "$path" ]] || \
       ! grep -Fq -- "$marker" "$path" 2>/dev/null; then
        legacy_record_ambiguous "$path"
        return 0
    fi
    legacy_array_contains "$path" "${LEGACY_OWNED[@]}" && return 0
    LEGACY_OWNED+=("$path")
    if [[ "$delete_after" -eq 1 ]]; then LEGACY_DELETE+=("$path"); LEGACY_SOURCE_COUNT=$((LEGACY_SOURCE_COUNT+1)); fi
}

legacy_add_snapshot_candidate() {
    [[ -e ai_snapshot.json || -L ai_snapshot.json ]] || return 0
    if [[ -f ai_snapshot.json ]] && grep -Eq '"schema_version"[[:space:]]*:[[:space:]]*2([,[:space:]}]|$)' ai_snapshot.json; then
        return 0
    fi
    legacy_add_candidate ai_snapshot.json '"schema_version": 1' 1
}

