scan_legacy_task_dir() {
    local dir=$1 entry rel
    if [[ -L "$dir" || ! -d "$dir" ]]; then legacy_record_ambiguous "$dir"; return 0; fi
    LEGACY_DELETE_DIRS+=("$dir")
    while IFS= read -r -d '' entry; do
        rel=${entry#"$dir"/}
        case "$rel" in
            task.md) legacy_add_candidate "$entry" '# Task' 1 ;;
            ai_snapshot.json) legacy_add_candidate "$entry" '"schema_version": 1' 1 ;;
            verification.md) legacy_add_candidate "$entry" '# Verification' 1 ;;
            defect-rca.md) legacy_add_candidate "$entry" '# Defect RCA' 1 ;;
            *) legacy_record_ambiguous "$entry" ;;
        esac
    done < <(find "$dir" -mindepth 1 -print0)
}

scan_legacy_artifacts() {
    LEGACY_OWNED=(); LEGACY_AMBIGUOUS=(); LEGACY_DELETE=(); LEGACY_DELETE_DIRS=(); LEGACY_SOURCE_COUNT=0
    legacy_add_candidate spec.md 'Planner 负责维护本文件' 1
    legacy_add_candidate todo.md '# TODO' 1
    legacy_add_candidate evaluation.md '# Evaluation Report' 1
    legacy_add_candidate verification.md '# Verification Log' 1
    legacy_add_snapshot_candidate
    legacy_add_candidate scripts/task_new.sh 'DIR="tasks/TASK-${STAMP}-${SLUG}"' 1
    legacy_add_candidate prompts/task.md '# Task Sandbox Prompt' 1
    legacy_add_candidate prompts/init.md '# First-Round Initialization Prompt' 1
    legacy_add_candidate docs/ai/task-sandbox.md '# Task Sandbox' 1
    if [[ -e tasks/_template || -L tasks/_template ]]; then scan_legacy_task_dir tasks/_template; fi
    if [[ -d tasks ]]; then
        local d
        while IFS= read -r -d '' d; do
            scan_legacy_task_dir "$d"
        done < <(find tasks -mindepth 1 -maxdepth 1 -type d -name 'TASK-[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]-*' -print0)
    fi

    # 只有存在明确的 legacy 事实源时，才把共享模板纳入迁移分类。
    # 这使迁移后的重复调用稳定地报告“无迁移源”，而不会把新模板误报为歧义。
    if [[ "$LEGACY_SOURCE_COUNT" -gt 0 ]]; then
        local path marker delete_after
        while IFS='|' read -r path marker delete_after; do legacy_add_candidate "$path" "$marker" "$delete_after"; done <<'MAP'
CLAUDE.md|— AI Harness Index|0
AGENTS.md|— GPT/Codex Harness Index|0
PROJECT_ATTRIBUTION.md|autoai:project-attribution-document:v1|0
.clang-format|BasedOnStyle: Google|0
.claude/settings.json|Bash(bash scripts/context_reset_check.sh *)|0
.claude/skills/full-code-review/SKILL.md|name: full-code-review|0
.codex/skills/full-code-review/SKILL.md|name: full-code-review|0
.codex/skills/full-code-review/agents/openai.yaml|Use $full-code-review|0
.cursorrules|你是一位资深 C++ 工程师|0
.vscode/settings.json|C_Cpp.default.cppStandard|0
.vscode/extensions.json|github.copilot-chat|0
docs/ai/build.md|# Build Rules|0
docs/ai/check-rules.md|# Learned Check Rules|0
docs/ai/cpp.md|# C++ Rules|0
docs/ai/evaluation.md|# Evaluation Rules|0
docs/ai/golden-principles.md|# Golden Principles|0
docs/ai/quick-brief.md|# Quick Brief And Layered Reading|0
docs/ai/rca.md|# Defect RCA And Rule Self-Healing|0
docs/ai/testing.md|# Testing Rules|0
docs/ai/tooling.md|# AI Tooling|0
docs/ai/workflow.md|# Agent Workflow Rules|0
init.sh|scripts/context_reset_check.sh|0
prompts/planner.md|# Planner Prompt|0
prompts/generator.md|# Generator Prompt|0
prompts/evaluator.md|# Evaluator Prompt|0
prompts/handoff.md|# Handoff Prompt|0
prompts/resume.md|# Resume Prompt|0
prompts/full-code-review.md|# Full Code Review Prompt|0
prompts/rca.md|# RCA Prompt|0
prompts/debt-scan.md|# Technical Debt Scan Prompt|0
prompts/debt-fix.md|# Technical Debt Fix Prompt|0
scripts/ai_debt_scan.sh|TARGETS=()|0
scripts/attribution_check.sh|autoai:project-attribution-checker:v1|0
scripts/context_reset_check.sh|REQUIRED_FILES=(|0
scripts/evaluator_check.sh|# Evaluator Check|0
scripts/quick_brief_check.sh|# Quick Brief Check|0
scripts/rca_new.sh|DIR="${2:-rca}"|0
scripts/resume_from_snapshot.sh|# Resume From Snapshot|0
scripts/snapshot_update.sh|TASK="${1:-current-work}"|0
claude-progress.txt|# Claude Progress|1
session-state.md|# Session State|1
debt-register.md|# Technical Debt Register|1
defect-rca.md|# Defect RCA Log|1
MAP
        while IFS= read -r path; do
            [[ -e "$path" || -L "$path" ]] || continue
            [[ "$path" == .gitignore ]] && continue
            legacy_array_contains "$path" "${LEGACY_OWNED[@]}" || legacy_record_ambiguous "$path"
        done < <(migration_generated_paths)
    fi
}

print_migration_plan() {
    scan_legacy_artifacts
    echo '# OpenSpec migration dry-run'
    echo
    echo "Dependencies: git=$(command -v git) node=$(node --version) npm=$(command -v npm) npx=$(command -v npx)"
    echo "AutoAI-owned (${#LEGACY_OWNED[@]}):"
    local p
    for p in "${LEGACY_OWNED[@]}"; do printf '  - %s  sha256:%s\n' "$p" "$(sha256sum -- "$p"|awk '{print $1}')"; done
    echo "User-owned/preserved ($([[ -f .gitignore ]] && echo 1 || echo 0)):"
    [[ -f .gitignore ]] && printf '  - .gitignore  sha256:%s  (whole-file rollback copy; only managed patterns will be appended)\n' "$(sha256sum -- .gitignore|awk '{print $1}')"
    echo "Ambiguous (${#LEGACY_AMBIGUOUS[@]}):"
    for p in "${LEGACY_AMBIGUOUS[@]}"; do
        if [[ -f "$p" && ! -L "$p" ]]; then printf '  - %s  sha256:%s\n' "$p" "$(sha256sum -- "$p"|awk '{print $1}')"; else printf '  - %s  type:%s\n' "$p" "$(stat -c %F -- "$p" 2>/dev/null || echo unknown)"; fi
    done
    echo "Delete after verification (${#LEGACY_DELETE[@]} files, ${#LEGACY_DELETE_DIRS[@]} directories):"
    for p in "${LEGACY_DELETE[@]}"; do printf '  - %s\n' "$p"; done
    for p in "${LEGACY_DELETE_DIRS[@]}"; do printf '  - %s/\n' "$p"; done
    echo
    echo 'Will create: .ai-harness/migrations/<UTC timestamp>/ and openspec/changes/migrate-legacy-harness-<UTC timestamp>/'
    echo 'Will delete: only the paths in “Delete after verification”; tasks/ itself is preserved.'
    echo 'Plan: verified local backup -> migration change harness/legacy reference -> OpenSpec templates -> delete only confirmed legacy-only files -> activate migration change.'
    [[ "$LEGACY_SOURCE_COUNT" -gt 0 ]] || echo 'Result: no legacy migration source.'
    [[ "${#LEGACY_AMBIGUOUS[@]}" -eq 0 ]] || echo 'Result: formal migration is blocked until ambiguous paths are handled.'
}

preflight_migration_state() {
    if [[ -e openspec && ( ! -d openspec || -L openspec ) ]]; then die 4 "openspec 必须是非符号链接目录"; fi
    if [[ -d openspec && ! -f openspec/config.yaml ]]; then die 4 "检测到不完整 OpenSpec 目录（缺少 config.yaml）"; fi
    if [[ -f openspec/config.yaml ]]; then
        [[ ! -L openspec/config.yaml ]] || die 4 "openspec/config.yaml 不能是符号链接"
        local required_dir
        for required_dir in openspec/specs openspec/changes openspec/changes/archive; do
            [[ -d "$required_dir" && ! -L "$required_dir" ]] || die 4 "检测到不完整 OpenSpec 目录（缺少或不安全: $required_dir）"
        done
        [[ "$(openspec_schema)" == spec-driven ]] || die 4 "迁移不支持 custom schema"
    fi
    if find .claude .codex -mindepth 1 \( -name 'openspec-*' -o -name 'opsx' -o -name 'opsx-*' \) -print -quit 2>/dev/null | grep -q .; then die 4 "迁移不支持已安装的 OpenSpec Agent skills/commands"; fi
    if [[ -f ai_snapshot.json ]] && grep -q '"schema_version"[[:space:]]*:[[:space:]]*2' ai_snapshot.json; then
        node - ai_snapshot.json <<'NODE' || die 5 "OpenSpec snapshot v2 无效或已有 active change"
const fs=require('fs');const d=JSON.parse(fs.readFileSync(process.argv[2],'utf8'));
if(d.schema_version!==2||d.active_change!==null||d.archive_failure!==undefined&&d.archive_failure!==null)process.exit(1);
NODE
    fi
    preflight_managed_paths
}

existing_migration_for_current_sources() {
    [[ -d .ai-harness/migrations ]] || return 1
    node - .ai-harness/migrations "${LEGACY_OWNED[@]}" <<'NODE'
const fs=require('fs'),path=require('path'),crypto=require('crypto');
const [root,...sources]=process.argv.slice(2),wanted=new Map();
for(const p of sources){const b=fs.readFileSync(p);wanted.set(p,'sha256:'+crypto.createHash('sha256').update(b).digest('hex'))}
for(const ent of fs.readdirSync(root,{withFileTypes:true}).filter(x=>x.isDirectory()).sort()){
  const file=path.join(root,ent.name,'manifest.json'); if(!fs.existsSync(file))continue;
  try{const d=JSON.parse(fs.readFileSync(file,'utf8'));const got=new Map((d.files||[]).filter(x=>x.classification==='autoai-owned').map(x=>[x.source_path,x.sha256]));
    if(got.size===wanted.size&&[...wanted].every(([p,h])=>got.get(p)===h)){process.stdout.write(`${d.status||'unknown'}\t${d.change_name||''}\t${file}\n`);process.exit(0)}}catch{}
}
process.exit(1);
NODE
}

migration_sources_match_manifest() {
    local manifest=${1:?migration manifest required}
    node - "$manifest" <<'NODE'
const fs=require('fs'),crypto=require('crypto');const d=JSON.parse(fs.readFileSync(process.argv[2],'utf8'));
for(const x of d.files){let s,b;try{s=fs.lstatSync(x.source_path);if(!s.isFile()||s.isSymbolicLink())process.exit(1);b=fs.readFileSync(x.source_path)}catch{process.exit(1)}const h='sha256:'+crypto.createHash('sha256').update(b).digest('hex'),m=(s.mode&0o777).toString(8).padStart(3,'0');if(h!==x.sha256||m!==x.mode||b.length!==x.size)process.exit(1)}
NODE
}

migration_template_precondition() {
    local path=${1:?managed template path required}
    [[ -n "$MIGRATION_MANIFEST_PATH" && -f "$MIGRATION_MANIFEST_PATH" && ! -L "$MIGRATION_MANIFEST_PATH" ]] || return 1
    preflight_writable_path "$path"
    node - "$MIGRATION_MANIFEST_PATH" "$path" <<'NODE'
const fs=require('fs'),crypto=require('crypto');const [manifest,p]=process.argv.slice(2),d=JSON.parse(fs.readFileSync(manifest)),x=d.files.find(v=>v.source_path===p);let s;try{s=fs.lstatSync(p)}catch(e){if(e.code!=='ENOENT')throw e;if(x)process.exit(1);process.exit(0)}if(!x||!s.isFile()||s.isSymbolicLink())process.exit(1);const b=fs.readFileSync(p),h='sha256:'+crypto.createHash('sha256').update(b).digest('hex'),m=(s.mode&0o777).toString(8).padStart(3,'0');if(h!==x.sha256||m!==x.mode||b.length!==x.size)process.exit(1);
NODE
}

migration_remove_source() {
    local path=${1:?legacy source required} backup=${2:?migration backup required} moved
    moved="$backup/removed/$path"
    mkdir -p -- "$(dirname "$moved")"
    [[ ! -e "$moved" && ! -L "$moved" ]] || die 5 "迁移删除暂存路径冲突: $moved"
    mv -- "$path" "$moved" || die 5 "迁移源在删除前消失或不可移动: $path"
    if ! node - "$backup/manifest.json" "$path" "$moved" <<'NODE'
const fs=require('fs'),crypto=require('crypto');const [manifest,p,moved]=process.argv.slice(2),d=JSON.parse(fs.readFileSync(manifest)),x=d.files.find(v=>v.source_path===p);if(!x)process.exit(1);const s=fs.lstatSync(moved),b=fs.readFileSync(moved),h='sha256:'+crypto.createHash('sha256').update(b).digest('hex'),mode=(s.mode&0o777).toString(8).padStart(3,'0');if(!s.isFile()||s.isSymbolicLink()||h!==x.sha256||mode!==x.mode||b.length!==x.size)process.exit(1);
NODE
    then
        if [[ ! -e "$path" && ! -L "$path" ]]; then mkdir -p -- "$(dirname "$path")"; mv -- "$moved" "$path"; fi
        die 5 "迁移源在删除瞬间发生变化；已保留实际文件并停止: $path"
    fi
}

migration_worktree_is_clean() {
    [[ -z "$(git status --porcelain=v1 --untracked-files=all -- . \
        ':(exclude).ai-harness/locks' \
        ':(exclude).ai-harness/locks/**')" ]]
}

run_migration() {
    preflight_dependencies
    if [[ "$DRY_RUN" -eq 1 ]]; then print_migration_plan; return 0; fi
    scan_legacy_artifacts
    [[ "${#LEGACY_AMBIGUOUS[@]}" -eq 0 ]] || { printf '[ERR] ambiguous legacy path: %s\n' "${LEGACY_AMBIGUOUS[@]}" >&2; die 5 "迁移因所有权歧义停止"; }
    [[ "$LEGACY_SOURCE_COUNT" -gt 0 ]] || die 4 "没有可迁移的 legacy Harness（可能已完成迁移）"
    preflight_migration_state
    preflight_openspec_runner
    if [[ -f openspec/config.yaml ]]; then openspec_project_is_compatible || die 4 "现有 OpenSpec 项目与固定 1.6.0 list JSON 契约不兼容"; fi
    migration_worktree_is_clean || die 5 "正式迁移要求干净 Git 工作树"
    prepare_project_profile_input
    local existing
    if existing=$(existing_migration_for_current_sources 2>/dev/null); then
        case "$existing" in
            complete$'\t'*) die 4 "相同源 hash 的迁移已经完成：$existing" ;;
            *) die 5 "相同源 hash 已有未清理迁移记录，需人工检查后再运行：$existing" ;;
        esac
    fi
    collect_openspec_inputs
    acquire_setup_lock
    migration_worktree_is_clean || die 5 "迁移获取锁期间 Git 工作树发生变化；未创建备份、change 或修改 legacy 文件"
    scan_legacy_artifacts
    [[ "$LEGACY_SOURCE_COUNT" -gt 0 && "${#LEGACY_AMBIGUOUS[@]}" -eq 0 ]] || \
        die 5 "迁移源在获取锁期间发生变化；未写入迁移内容"
    preflight_migration_state
    if [[ -f openspec/config.yaml ]]; then openspec_project_is_compatible || die 5 "获取锁后 OpenSpec 项目兼容性检查失败"; fi
    local stamp change backup list validation new_change_json p d fresh=0 success=0 backup_complete=0 legacy_mutation_started=0
    local had_specs=0 had_changes=0 had_archive=0 migration_step=allocate-backup
    stamp=$(date -u +%Y%m%dt%H%M%S%Nz)
    change="migrate-legacy-harness-$stamp"
    backup=".ai-harness/migrations/$stamp"
    list=$(mktemp "${TMPDIR:-/tmp}/autoai-migration-list.XXXXXX")
    mkdir -p .ai-harness/migrations
    mkdir "$backup" || die 5 "迁移目录已存在，拒绝复用: $backup"
    mkdir "$backup/legacy"
    for p in "${LEGACY_OWNED[@]}"; do printf 'autoai-owned\0%s\0' "$p" >> "$list"; done
    if [[ -e .gitignore || -L .gitignore ]]; then
        [[ -f .gitignore && ! -L .gitignore ]] || die 5 ".gitignore 不是普通文件"
        printf 'rollback-input\0.gitignore\0' >> "$list"
    fi
    [[ -f openspec/config.yaml ]] || fresh=1
    [[ -d openspec/specs ]] && had_specs=1
    [[ -d openspec/changes ]] && had_changes=1
    [[ -d openspec/changes/archive ]] && had_archive=1

    migration_recover() {
        local rc=$? generated
        set +e
        if [[ "$success" -ne 1 ]]; then
            if [[ "$backup_complete" -eq 1 ]]; then
                if [[ "$fresh" -eq 1 ]]; then
                    if [[ -e openspec || -L openspec ]]; then
                        if [[ ! -e "$backup/failed-openspec" && ! -L "$backup/failed-openspec" ]]; then
                            mv -- openspec "$backup/failed-openspec"
                        fi
                    fi
                else
                    if [[ -e "openspec/changes/$change" || -L "openspec/changes/$change" ]]; then
                        if [[ ! -e "$backup/failed-change" && ! -L "$backup/failed-change" ]]; then
                            mv -- "openspec/changes/$change" "$backup/failed-change"
                        fi
                    fi
                fi
                if [[ "$legacy_mutation_started" -eq 1 && -d "$backup/legacy" ]]; then
                    # 只恢复缺失的原文件。若当前位置已有不同内容，可能是并发用户写入，绝不覆盖。
                    while IFS= read -r -d '' generated; do
                        generated=${generated#"$backup/legacy/"}
                        if [[ ! -e "$generated" && ! -L "$generated" ]]; then
                            mkdir -p -- "$(dirname "$generated")"
                            cp -p -- "$backup/legacy/$generated" "$generated"
                        fi
                    done < <(find "$backup/legacy" -type f -print0)
                fi
            fi
            if [[ "$PROJECT_PROFILE_INSTALLED" -eq 1 && -f .ai-harness/project-profile.json && ! -L .ai-harness/project-profile.json ]]; then
                if [[ "$(trusted_project_profile_digest .ai-harness/project-profile.json 2>/dev/null || true)" == "$PROJECT_PROFILE_EXPECTED_SHA" ]]; then
                    rm -f -- .ai-harness/project-profile.json
                    PROJECT_PROFILE_INSTALLED=0
                else
                    echo '[ERR] migration recovery left a changed Project Profile for manual inspection' >&2
                fi
            fi
            mkdir -p .ai-harness
            [[ -e .ai-harness/.gitignore ]] || printf '*\n' > .ai-harness/.gitignore
            if [[ -f "$backup/manifest.json" ]]; then node - "$backup/manifest.json" "$rc" "$migration_step" "$fresh" "$change" "$legacy_mutation_started" <<'NODE' || true
const fs=require('fs'),crypto=require('crypto');const [f,rc,step,fresh,change,mutated]=process.argv.slice(2),d=JSON.parse(fs.readFileSync(f)),issues=[];
for(const x of d.files){try{const b=fs.readFileSync(x.source_path),s=fs.statSync(x.source_path),h='sha256:'+crypto.createHash('sha256').update(b).digest('hex'),m=(s.mode&0o777).toString(8).padStart(3,'0');if(h!==x.sha256||m!==x.mode)issues.push(x.source_path+': hash/mode mismatch')}catch{issues.push(x.source_path+': missing')}}
if(fresh==='1'&&fs.existsSync('openspec'))issues.push('openspec/: transaction-created path remains');
if(fresh!=='1'&&fs.existsSync('openspec/changes/'+change))issues.push('openspec/changes/'+change+': transaction-created change remains');
if(mutated==='1')issues.push('managed-template mutation started; generated paths were preserved for manual recovery');
d.status='failed';d.failed_at=new Date().toISOString().replace('.000Z','Z');d.failure_exit_code=Number(rc);d.failure_step=step;d.recovery_status=issues.length?'manual-attention-required':'restored';d.manual_attention=issues;
fs.writeFileSync(f,JSON.stringify(d,null,2)+'\n');if(issues.length)console.error('[ERR] migration recovery requires manual attention: '+issues.join(', '));
NODE
            fi
        fi
        rm -f -- "$list"
        [[ -z "${validation:-}" ]] || rm -f -- "$validation"
        [[ -z "${new_change_json:-}" ]] || rm -f -- "$new_change_json"
        release_setup_lock
        return "$rc"
    }
    trap migration_recover EXIT
    trap 'exit 130' INT
    trap 'exit 143' TERM
    trap 'exit 129' HUP

    migration_step=write-preparing-manifest
    node - "$list" "$backup/manifest.json" "$stamp" "$change" <<'NODE'
const fs=require('fs'),crypto=require('crypto');const [list,out,id,change]=process.argv.slice(2),raw=fs.readFileSync(list).toString('utf8').split('\0');raw.pop();
if(raw.length%2)process.exit(5);const files=[];for(let i=0;i<raw.length;i+=2){const classification=raw[i],p=raw[i+1],b=fs.readFileSync(p),s=fs.statSync(p);files.push({source_path:p,classification,size:b.length,mode:(s.mode&0o777).toString(8).padStart(3,'0'),sha256:'sha256:'+crypto.createHash('sha256').update(b).digest('hex')})}
fs.writeFileSync(out,JSON.stringify({schema_version:1,migration_id:id,change_name:change,status:'preparing',started_at:new Date().toISOString().replace('.000Z','Z'),files},null,2)+'\n');
NODE

    migration_step=copy-and-verify-local-backup
    while IFS= read -r -d '' p <&3; do
        IFS= read -r -d '' d <&3 || die 5 "迁移备份列表损坏"
        mkdir -p "$backup/legacy/$(dirname "$d")"
        cp -p -- "$d" "$backup/legacy/$d"
        [[ "$(sha256sum -- "$d"|awk '{print $1}')" == "$(sha256sum -- "$backup/legacy/$d"|awk '{print $1}')" ]] || die 5 "备份验签失败: $d"
    done 3< "$list"
    backup_complete=1
    migration_sources_match_manifest "$backup/manifest.json" || die 5 "迁移源在备份后发生变化；未进入任何 legacy 覆盖或删除步骤"

    migration_step=initialize-or-validate-openspec
    if [[ "$fresh" -eq 1 ]]; then
        write_initial_openspec_config
        run_pinned_openspec init . --tools none --profile core || die 5 "迁移期间 OpenSpec init 失败"
        if find .claude .codex -mindepth 1 \( -name 'openspec-*' -o -name 'opsx' -o -name 'opsx-*' \) -print -quit 2>/dev/null | grep -q .; then
            die 5 "迁移期间 OpenSpec init 生成了不支持的 /opsx Agent assets；保留现场供人工恢复"
        fi
    fi
    mkdir -p openspec/specs openspec/changes/archive
    if [[ "$fresh" -eq 1 ]]; then
        validation=$(mktemp "${TMPDIR:-/tmp}/autoai-migration-validation.XXXXXX")
        if ! run_pinned_openspec validate --all --strict --json --no-interactive > "$validation" || \
           ! validation_json_is_clean "$validation"; then
            rm -f -- "$validation"
            die 5 "迁移初始化后的 OpenSpec validation 失败"
        fi
        rm -f -- "$validation"
    fi

    migration_step=create-migration-change
    [[ ! -e "openspec/changes/$change" ]] || die 5 "迁移 change 已存在"
    new_change_json=$(mktemp "${TMPDIR:-/tmp}/autoai-migration-new-change.XXXXXX")
    run_pinned_openspec new change "$change" --json > "$new_change_json" || die 5 "无法创建迁移 change"
    node - "$new_change_json" "$change" <<'NODE' || die 5 "迁移 change 的 OpenSpec JSON/文件系统 contract 无效"
const fs=require('fs'),path=require('path');const [file,id]=process.argv.slice(2),root=process.cwd(),v=JSON.parse(fs.readFileSync(file)),c=v?.change,target=path.resolve(root,'openspec','changes',id);if(!c||typeof c!=='object'||c.id!==id||c.schema!=='spec-driven'||typeof c.path!=='string'||typeof c.metadataPath!=='string'||!path.isAbsolute(c.path)||!path.isAbsolute(c.metadataPath)||path.resolve(c.path)!==target||path.resolve(c.metadataPath)!==path.join(target,'.openspec.yaml'))process.exit(1);const st=fs.lstatSync(target),mt=fs.lstatSync(path.join(target,'.openspec.yaml')),entries=fs.readdirSync(target);if(!st.isDirectory()||st.isSymbolicLink()||!mt.isFile()||mt.isSymbolicLink()||entries.length!==1||entries[0]!=='.openspec.yaml')process.exit(1);
NODE
    rm -f -- "$new_change_json"; new_change_json=
    mkdir -p "openspec/changes/$change/harness/legacy"
    for p in "${LEGACY_OWNED[@]}"; do
        mkdir -p "openspec/changes/$change/harness/legacy/$(dirname "$p")"
        cp -p -- "$backup/legacy/$p" "openspec/changes/$change/harness/legacy/$p"
    done
    cat > "openspec/changes/$change/harness/legacy/MIGRATION.md" <<EOF
# Legacy Harness migration reference

This directory is a byte-for-byte audit copy of confirmed legacy Harness material.
It is non-canonical: Planner must reconstruct proposal, delta specs, design and tasks
from project behavior and human review. No capability or delta was inferred automatically.

Migration ID: $stamp
EOF
    migration_step=verify-audit-copy
    node - "$backup/manifest.json" <<'NODE'
const fs=require('fs'),crypto=require('crypto');const d=JSON.parse(fs.readFileSync(process.argv[2]));
for(const x of d.files){const roots=['.ai-harness/migrations/'+d.migration_id+'/legacy'];if(x.classification==='autoai-owned')roots.push('openspec/changes/'+d.change_name+'/harness/legacy');for(const root of roots){const p=root+'/'+x.source_path,b=fs.readFileSync(p),h='sha256:'+crypto.createHash('sha256').update(b).digest('hex');if(h!==x.sha256||b.length!==x.size)process.exit(5)}}
NODE

    migration_step=install-openspec-harness
    migration_sources_match_manifest "$backup/manifest.json" || die 5 "迁移源在备份后发生变化；未进入任何 legacy 覆盖或删除步骤"
    legacy_mutation_started=1
    MIGRATION_MANIFEST_PATH="$backup/manifest.json"
    MIGRATION_OVERWRITE=1
    write_openspec_runner; install_project_profile; write_governance_templates; write_control_scripts; write_project_portability_scripts; write_project_coordination_scripts; write_integration_scripts; write_change_scripts; write_utility_scripts; write_fingerprint_script; write_footprint_script; write_task_verify_script; write_evaluator_script; write_archive_script; write_openspec_manifest
    migration_template_precondition .gitignore || die 5 "迁移期间 .gitignore 在追加前发生变化"
    append_managed_gitignore
    migration_step=verify-generated-harness
    node --check scripts/manifest_policy.js >/dev/null || die 5 "生成的 manifest policy 语法无效"
    node scripts/manifest_policy.js >/dev/null || die 5 "生成的 manifest/所有权策略不一致"
    scripts/project_profile.sh --check >/dev/null || die 5 "迁移后的 Project Profile 无效"
    AUTOAI_SETUP_SOURCE="$SETUP_SOURCE_PATH" \
      AUTOAI_SETUP_TEST_ROOT="$SETUP_SOURCE_DIR/tests/openspec-integration/cases" \
      scripts/workflow_contract_check.sh >/dev/null || die 5 "迁移后的工作流契约不一致"
    scripts/attribution_check.sh --quiet || die 5 "生成的项目署名契约无效"
    while IFS= read -r p; do
        case "$p" in *.sh) bash -n "$p" || die 5 "生成的 Shell 模板语法无效: $p" ;; esac
    done < <(migration_generated_paths)

    migration_step=remove-confirmed-legacy
    for p in "${LEGACY_DELETE[@]}"; do migration_remove_source "$p" "$backup"; done
    for d in "${LEGACY_DELETE_DIRS[@]}"; do rmdir -- "$d" 2>/dev/null || die 5 "Task 目录仍含未分类内容，拒绝删除: $d"; done

    migration_step=create-openspec-state
    write_openspec_state
    mkdir -p "openspec/changes/$change/harness"
    cat > "openspec/changes/$change/harness/ai_snapshot.json" <<'JSON'
{
  "schema_version": 4,
  "phase": "planning",
  "planned_base_specs_fingerprint": null,
  "planned_change_fingerprint": null,
  "planned_tdd_policy_sha256": null,
  "planned_integration_completeness_sha256": null,
  "planning_approved_at": null,
  "implementation_base_commit": null,
  "adopted_preexisting_paths": [],
  "implementation_baselined_at": null,
  "current_step": "reconstruct migration planning artifacts",
  "next_step": "review legacy reference and author proposal/specs/design/tasks"
}

JSON
    printf '{\n  "schema_version": 3,\n  "change_name": "%s",\n  "migration": null,\n  "tasks": []\n}\n' "$change" > "openspec/changes/$change/harness/verification.json"
    printf '# Verification — %s\n\n' "$change" > "openspec/changes/$change/harness/verification.md"; printf '# Evaluation history — %s\n\n' "$change" > "openspec/changes/$change/harness/evaluation.md"; printf '# Defect RCA — %s\n\n' "$change" > "openspec/changes/$change/harness/defect-rca.md"
    node - "$change" <<'NODE'
const fs=require('fs'),d=JSON.parse(fs.readFileSync('ai_snapshot.json'));d.active_change=process.argv[2];d.phase='planning';d.current_step='legacy-reference-preserved';d.next_step='Planner reconstructs canonical OpenSpec artifacts; no semantic translation was performed';d.updated_at=new Date().toISOString().replace('.000Z','Z');fs.writeFileSync('.snapshot-migrate',JSON.stringify(d,null,2)+'\n');fs.renameSync('.snapshot-migrate','ai_snapshot.json');
NODE
    migration_step=complete-manifest
    node - "$backup/manifest.json" <<'NODE'
const fs=require('fs'),crypto=require('crypto');const f=process.argv[2],d=JSON.parse(fs.readFileSync(f)),parts=[];for(const x of d.files.filter(x=>x.classification==='autoai-owned')){const b=fs.readFileSync('openspec/changes/'+d.change_name+'/harness/legacy/'+x.source_path),h='sha256:'+crypto.createHash('sha256').update(b).digest('hex');if(h!==x.sha256)process.exit(5);parts.push(x.source_path+'\0'+h+'\n')}d.status='complete';d.completed_at=new Date().toISOString().replace('.000Z','Z');d.final_audit_set_sha256='sha256:'+crypto.createHash('sha256').update(parts.sort().join('')).digest('hex');fs.writeFileSync(f,JSON.stringify(d,null,2)+'\n');
NODE
    success=1
    rm -f -- "$list"; release_setup_lock; trap - EXIT INT TERM HUP
    ok "legacy Harness 已安全保全到 $backup 和 openspec/changes/$change/harness/legacy/"
    echo "Active migration change: $change"
}

case "$WORKFLOW_MODE" in
    detect)
        is_git_root || die 3 "必须从 Git 仓库根目录运行项目探测"
        run_project_detection
        ;;
    openspec)
        run_openspec_harness
        ;;
    migration)
        run_migration
        ;;
    *)
        die 2 "未知 workflow mode: $WORKFLOW_MODE"
        ;;
esac
